@forager.tool
async def choose_next_function(ctx: RunContext[AntDeps], current_function: str) -> str:
    neighbors = ctx.deps.code_graph.get_neighbors(current_function)
    if not neighbors: return current_function  # dead end
    pheromones = {n: ctx.deps.pheromone_cache.read(f'bug:{n}')?.intensity ?? 1.0 for n in neighbors}
    complexities = {n: ctx.deps.code_graph.get_complexity(n) for n in neighbors}
    probs = calculate_probabilities(neighbors, pheromones, complexities, ctx.deps.config.aco.alpha, ctx.deps.config.aco.beta)
    return select_next(neighbors, probs, ctx.deps.rng)

