@forager.tool
async def report_bug(ctx: RunContext[AntDeps], function_name: str, description: str, severity: int, confidence: float) -> str:
    if confidence >= ctx.deps.config.min_confidence and severity >= 3:
        pheromone = BugPheromone(...)
        ctx.deps.pheromone_cache.deposit(f'bug:{function_name}', pheromone, ttl=7*24*3600)
        return 'Bug reported and pheromone deposited'
    return 'Bug logged but below threshold'

@forager.tool
async def get_pheromone_trail(ctx: RunContext[AntDeps], module: str) -> list[dict]:
    return [p.model_dump() for p in ctx.deps.pheromone_cache.read_pattern(f'bug:{module}')]

